SELECT CASE WHEN duration_sec >= 529 THEN 'high' WHEN duration_sec >= 182 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, page, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(event_type))) AS event_type_values FROM web_events WHERE duration_sec = 224 AND event_type != 'search' AND duration_sec < 184 GROUP BY 1, 2;
